}

export interface PublicChallengerStatus {
  deployed: boolean;
  loaded: boolean;
  authority: "SHADOW_ONLY" | null;
  run_id: string | null;
  created_at: string | null;
  candidate: string | null;
  feature_schema: string | null;
  decision_gate: number | null;
